-- Partner branding, phase one: the schema, and Tradeshift in it.
--
-- A subscriber whose email domain belongs to a partner organisation can
-- have that partner's mark placed on the PDFs they generate -- the ROI
-- plan and the country compliance guide -- on the first page, reading
-- GENERATED BY. Nothing else changes for them yet.
--
-- WHY THREE TABLES AND NOT ONE. The obvious shape is a single row per
-- domain carrying a colour and a logo. It breaks on the first partner
-- with two domains: the palette is then stored once per domain, and this
-- codebase has been bitten by one-fact-in-many-places often enough this
-- month to know how that ends. The partner is the entity; the domains
-- hang off it, and so does the palette.
--
-- WHY THE PALETTE IS ROWS AND NOT ELEVEN COLUMNS. Two reasons, one of
-- which is this file's own machinery. A partner overriding three
-- properties should say three things, not eight NULLs that have to mean
-- "leave it". And a contrast check written against rows is an assertion
-- this runner can enforce; the same check against eleven columns is
-- eleven assertions that have to be edited whenever the palette grows.
--
-- WHY THE PALETTE TABLE EXISTS WITH NOTHING IN IT. The site theme is
-- phase two and is blocked on Tradeshift sending brand hex values -- the
-- logo file they sent is pure black on white and carries no colour.
-- Creating the table now costs nothing and means phase two is an INSERT
-- rather than a schema change on a live database.
--
-- WHY THERE IS NO _translations SIBLING, deliberately. Every other
-- content table here has one. The only human-readable field in these
-- three is a company name, which is a proper noun and identical in all
-- four languages. This is not an oversight and should not be "fixed".

CREATE TABLE IF NOT EXISTS partners (
  id            INTEGER PRIMARY KEY,
  slug          TEXT NOT NULL UNIQUE,
  display_name  TEXT NOT NULL,
  -- Paths to static assets, never the bytes. The migration chain is
  -- replayed end to end by the offline harness before anything ships;
  -- a few hundred kilobytes of base64 per partner would make every
  -- replay heavier and every diff unreadable, for a file the browser
  -- has to fetch as an asset anyway. tests/partner-branding.mjs asserts
  -- that every path here resolves to a file that exists, which is the
  -- half of this SQL cannot check.
  mark_dark     TEXT NOT NULL,
  -- Nullable on purpose: the reverse lockup for a dark ground. Tradeshift
  -- has not supplied one and the inverted stand-in used in the mock-up is
  -- not an approved asset, so this stays NULL rather than carrying
  -- something nobody signed off. Nothing in phase one reads it.
  mark_light    TEXT,
  active        INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS partner_domains (
  partner_id  INTEGER NOT NULL REFERENCES partners(id),
  -- UNIQUE because a domain resolves to at most one partner. That is what
  -- keeps the preference a single checkbox rather than a list, and it is
  -- worth having the database say so rather than the UI assuming it.
  --
  -- MATCHED EXACTLY, never as a suffix. A suffix match on 'tradeshift.com'
  -- also matches 'tradeshift.com.example.net', which anyone can register.
  -- One row per real domain costs nothing.
  domain      TEXT NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS partner_palette (
  partner_id  INTEGER NOT NULL REFERENCES partners(id),
  prop        TEXT NOT NULL,
  value       TEXT NOT NULL,
  PRIMARY KEY (partner_id, prop)
);

CREATE INDEX IF NOT EXISTS idx_partner_domains_domain ON partner_domains(domain);

-- ---- Tradeshift ----
INSERT INTO partners (slug, display_name, mark_dark, mark_light, active)
SELECT 'tradeshift', 'Tradeshift', 'images/partners/tradeshift-dark.png', NULL, 1
 WHERE NOT EXISTS (SELECT 1 FROM partners WHERE slug = 'tradeshift');

-- One domain to start with. Tradeshift will have others; each is a row,
-- added when somebody has confirmed it rather than guessed at it.
INSERT INTO partner_domains (partner_id, domain)
SELECT id, 'tradeshift.com' FROM partners WHERE slug = 'tradeshift'
 AND NOT EXISTS (SELECT 1 FROM partner_domains WHERE domain = 'tradeshift.com');

-- ---- what this migration claims it did ----
-- One partner, active, with a dark mark and no light one.
-- ASSERT: SELECT count(*) FROM partners WHERE slug = 'tradeshift' AND active = 1 AND mark_dark <> '' AND mark_light IS NULL = 1
-- One domain, resolving to it.
-- ASSERT: SELECT count(*) FROM partner_domains d JOIN partners p ON p.id = d.partner_id WHERE p.slug = 'tradeshift' = 1
-- The palette table exists and is deliberately empty until brand values arrive.
-- ASSERT: SELECT count(*) FROM partner_palette = 0
--
-- ---- and what must stay true ----
-- Every domain resolves to a partner that exists. A row pointing at a
-- deleted partner would brand nobody and look like a configuration
-- problem for as long as it took someone to notice.
-- ASSERT ALWAYS: SELECT count(*) FROM partner_domains d WHERE NOT EXISTS (SELECT 1 FROM partners p WHERE p.id = d.partner_id) = 0
-- No domain is stored with an @, a leading dot, or uppercase. The lookup
-- lowercases the address's domain and compares it exactly, so a row
-- stored as 'Tradeshift.com' or '@tradeshift.com' silently matches
-- nothing -- the one failure mode of this table that is invisible from
-- the outside, because an unbranded document looks exactly like a
-- reader who turned branding off.
-- ASSERT ALWAYS: SELECT count(*) FROM partner_domains WHERE domain <> lower(domain) OR domain LIKE '%@%' OR domain LIKE '.%' = 0
-- Every palette row belongs to a partner and names a custom property.
-- Phase two will fill this table; the shape it must arrive in is stated
-- here, while it is still cheap to state.
-- ASSERT ALWAYS: SELECT count(*) FROM partner_palette WHERE prop NOT LIKE '--%' = 0
-- ASSERT ALWAYS: SELECT count(*) FROM partner_palette pp WHERE NOT EXISTS (SELECT 1 FROM partners p WHERE p.id = pp.partner_id) = 0
